const servicePages: ServicePage[] = [
  { slug: 'ga4-implementation', title: 'GA4 implementation built around how your business measures customers and revenue.', eyebrow: 'Measure / GA4 implementation', seoTitle: 'GA4 Implementation Services for Reliable Conversion Tracking | Fixify', description: 'Fixify implements GA4 around your business goals, including events, conversions, ecommerce, cross-domain tracking, QA, documentation and CRM connections.', primaryKeyword: 'GA4 implementation agency', intro: 'GA4 should reflect the way your business works—not force your team to interpret a collection of disconnected events. Fixify plans, implements and validates GA4 for lead generation, ecommerce, SaaS, subscription and multi-domain businesses.', problem: 'When properties grow without a measurement model, events become hard to name, conversions become hard to trust and revenue becomes difficult to reconcile.', deliverables: ['Measurement plan and event taxonomy', 'Property, data-stream and configuration review', 'Events, parameters, conversions and audiences', 'Ecommerce, lead and cross-domain tracking', 'Google Ads, CRM and BigQuery connections', 'Testing evidence, documentation and handover'], process: ['Define the business questions and acceptance criteria', 'Design the event model, data layer and ownership', 'Implement the configuration in your accounts', 'Validate events, conversions, consent and revenue paths', 'Handover documentation and an operating checklist'], faq: [{ question: 'Can you work with an existing GA4 property?', answer: 'Yes. We can audit what is already there, preserve useful history and prioritize changes rather than forcing a rebuild.' }, { question: 'Do you implement ecommerce tracking?', answer: 'Yes, including product, cart, checkout, purchase, refund and value definitions where the platform supports them.' }], cta: 'Request a GA4 implementation assessment', related: [{ label: 'GA4 Audit', href: '/ga4-audit/' }, { label: 'Measurement Strategy', href: '/measurement-strategy/' }, { label: 'BigQuery & BI', href: '/ga4-bigquery-bi/' }] },
  { slug: 'ga4-audit', title: 'Find out why your GA4 data cannot be trusted—and what to fix first.', eyebrow: 'Measure / GA4 audit', seoTitle: 'GA4 Audit Services | Find and Fix Tracking Problems | Fixify', description: 'Find duplicate events, missing conversions, incorrect revenue and GA4 data-quality issues with a structured GA4 audit from Fixify.', primaryKeyword: 'GA4 audit', intro: 'If GA4, Google Ads and your CRM report different numbers, adding more dashboards will not solve the problem. You need to find where the measurement chain breaks.', problem: 'A GA4 audit is useful when the issue is unclear, the property has changed hands or stakeholders need a severity-ranked view of what is reliable and what is not.', deliverables: ['Property and data-stream review', 'Events, parameters and conversion configuration', 'Data-layer, GTM and ecommerce review', 'Cross-domain, Ads, CRM and offline connections', 'Consent, attribution and discrepancy review', 'Severity-ranked findings, evidence and remediation roadmap'], process: ['Scope the business questions and critical journeys', 'Review configuration, implementation and reported data', 'Test priority paths and compare system outputs', 'Rank findings by impact, confidence and effort', 'Present quick wins, structural fixes and validation steps'], faq: [{ question: 'Will the audit change my tracking?', answer: 'The default audit is read-only. If you want remediation, we can scope it as a separate implementation phase.' }, { question: 'What do you need from our team?', answer: 'Read-only access, a list of important journeys and examples of the discrepancies you are seeing are usually enough to start.' }], cta: 'Request a GA4 audit scope', related: [{ label: 'Tracking Fix', href: '/tracking-fix/' }, { label: 'Google Tag Manager', href: '/google-tag-manager/' }, { label: 'Measurement QA', href: '/measurement-qa-monitoring/' }] },
  { slug: 'google-tag-manager', title: 'Build a GTM container that is easier to debug, safer to release and simpler to maintain.', eyebrow: 'Govern / Google Tag Manager', seoTitle: 'Google Tag Manager Consultant and Implementation Services | Fixify', description: 'Build, clean up and govern Google Tag Manager with better data layers, naming, permissions, release QA and conversion tracking.', primaryKeyword: 'Google Tag Manager consultant', intro: 'GTM can reduce unnecessary developer dependency, but good analytics still requires coordination between marketing, engineering, product and privacy teams.', problem: 'Containers become risky when nobody knows which tag owns a conversion, what a trigger depends on or how a release was validated.', deliverables: ['Container audit and tag inventory', 'Trigger, variable and data-layer architecture', 'Naming conventions, permissions and workspaces', 'Custom templates and consent governance', 'Preview, regression and release QA', 'Developer handoff and maintenance playbook'], process: ['Map the current container and critical tags', 'Define a cleaner data layer and naming model', 'Refactor or implement the required components', 'Test browser, consent and conversion behavior', 'Release with documentation and rollback guidance'], faq: [{ question: 'Can you clean up an existing GTM container?', answer: 'Yes. We can inventory, classify and prioritize tags, then remove or refactor items with a documented release plan.' }, { question: 'Do you work with developers?', answer: 'Yes. Data-layer requirements and acceptance criteria are written so engineering teams can implement and test them clearly.' }], cta: 'Request a GTM architecture review', related: [{ label: 'Tracking Fix', href: '/tracking-fix/' }, { label: 'Consent Mode & CMP', href: '/consent-mode-cmp/' }, { label: 'Server-Side Tagging', href: '/server-side-tagging/' }] },
  { slug: 'tracking-fix', title: 'Fix one clearly defined tracking problem without starting with a massive project.', eyebrow: 'Govern / tracking fix', seoTitle: 'GA4 and Conversion Tracking Fixes | Fixify', description: 'Fix duplicate purchases, missing leads, wrong revenue, broken cross-domain tracking and other GA4, GTM and conversion tracking problems.', primaryKeyword: 'GA4 tracking fix', intro: 'Some tracking problems need a focused fix. Others are symptoms of a larger measurement failure. Fixify helps you identify the difference, scope the issue and validate the fix before handover.', problem: 'Duplicate purchases, missing lead events, wrong purchase values, consent-blocked tags and platform mismatches often look different but share a broken measurement dependency.', deliverables: ['Issue reproduction and impact assessment', 'Event, parameter and trigger diagnosis', 'Focused implementation change', 'Browser/server and consent validation', 'Before/after evidence and rollback note', 'Boundary recommendation if a wider audit is needed'], process: ['Describe the issue and the path where it occurs', 'Reproduce the behavior and isolate the dependency', 'Implement the smallest defensible fix', 'Validate the signal across relevant systems', 'Document what changed and what remains out of scope'], faq: [{ question: 'What issues are a fit for this service?', answer: 'Contained issues such as duplicate purchases, missing leads, wrong values, broken cross-domain tracking and consent-blocked tags.' }, { question: 'Will you tell us if the issue is bigger?', answer: 'Yes. If the symptom points to a wider architecture or governance problem, we will explain the boundary before expanding the work.' }], cta: 'Describe a tracking problem', related: [{ label: 'GA4 Audit', href: '/ga4-audit/' }, { label: 'Google Tag Manager', href: '/google-tag-manager/' }, { label: 'Measurement QA', href: '/measurement-qa-monitoring/' }] },
  { slug: 'consent-mode-cmp', title: 'Make your analytics and advertising tags respond correctly to user consent.', eyebrow: 'Protect / consent and CMP', seoTitle: 'Consent Mode and CMP Implementation Services | Fixify', description: 'Implement and validate consent-aware analytics, Google Consent Mode, CMP integrations, regional behavior, tag controls and measurement QA.', primaryKeyword: 'Consent Mode v2 implementation', intro: 'Fixify implements and validates the technical measurement behavior required by your consent design. Legal basis, privacy policies, contracts and regulatory interpretation remain with your legal and privacy stakeholders.', problem: 'A CMP can be installed and still leave unclear defaults, inconsistent regional behavior, uncontrolled destinations or untested consent-state transitions.', deliverables: ['Consent signals and tag behavior map', 'CMP and GTM integration', 'Regional defaults and Consent Mode setup', 'Consent-state QA across browsers and regions', 'Data redaction, minimization and destination controls', 'Technical documentation for privacy and marketing teams'], process: ['Review the consent design and destination inventory', 'Map consent states to measurement behavior', 'Implement configuration and regional rules', 'Test granted, denied and partial states', 'Document assumptions, limitations and operating ownership'], faq: [{ question: 'Does Fixify provide legal compliance advice?', answer: 'No. We implement and validate technical behavior against the consent design supplied by your legal and privacy stakeholders.' }, { question: 'Can consent work with server-side tracking?', answer: 'Yes, but consent propagation, destination rules and identity assumptions must be designed and tested together.' }], cta: 'Request a consent measurement gap analysis', related: [{ label: 'Google Tag Manager', href: '/google-tag-manager/' }, { label: 'Server-Side Tagging', href: '/server-side-tagging/' }, { label: 'Measurement QA', href: '/measurement-qa-monitoring/' }] },
  { slug: 'server-side-tagging', title: 'Move the right measurement work closer to the source—with consent, routing, cost and data quality designed in.', eyebrow: 'Connect / server-side tagging', seoTitle: 'Server-Side GTM and Server-Side Tracking Services | Fixify', description: 'Design server-side GTM, first-party routing, consent-aware event delivery, deduplication and backend conversion measurement with Fixify.', primaryKeyword: 'server-side GTM agency', intro: 'Server-side tagging is not automatically privacy-safe, automatically first-party or a complete CDP, CRM or BI solution. The result depends on event design, consent, identity, deduplication, domain configuration, infrastructure and destination rules.', problem: 'Moving events server-side can improve control, but it also introduces hosting, routing, cost, observability and ownership decisions that need to be made explicitly.', deliverables: ['Browser-to-server architecture', 'Server container clients, tags and transformations', 'Consent and destination rules', 'Event IDs and browser/server deduplication', 'Custom domain and first-party setup', 'Cost, rollout, rollback and monitoring assumptions'], process: ['Assess whether server-side is appropriate for the use case', 'Design the smallest reliable browser/server architecture', 'Configure the container and destination routing', 'Test consent, delivery, deduplication and failure paths', 'Handover operational ownership and cost assumptions'], faq: [{ question: 'Does every business need server-side tagging?', answer: 'No. We recommend it when the use case justifies the added architecture, cost and operating responsibility.' }, { question: 'Can you help with Cloud Run infrastructure?', answer: 'We can document the infrastructure assumptions, configuration requirements and operating handover for the chosen hosting model.' }], cta: 'Book a server-side readiness assessment', related: [{ label: 'Consent Mode & CMP', href: '/consent-mode-cmp/' }, { label: 'CRM & Offline Conversions', href: '/crm-offline-conversions/' }, { label: 'BigQuery & BI', href: '/ga4-bigquery-bi/' }] },
  { slug: 'crm-offline-conversions', title: 'Measure the journey from first click to qualified revenue.', eyebrow: 'Connect / CRM and offline conversions', seoTitle: 'CRM and Offline Conversion Tracking Services | Fixify', description: 'Connect qualified leads, CRM stages, closed revenue, webhooks and offline conversions to GA4, Google Ads, Meta and reporting systems.', primaryKeyword: 'CRM offline conversions', intro: 'Form submissions are only the beginning. Fixify connects campaign, landing-page, form, call, CRM stage and closed-revenue data so your marketing team can optimize toward the leads sales actually values.', problem: 'Marketing can measure form submissions while sales and finance use different lifecycle definitions, identifiers and revenue records.', deliverables: ['Lifecycle-stage definitions', 'CRM identifiers, consent and matching rules', 'Webhook and API architecture', 'Google Ads, Meta and analytics mappings', 'Deduplication and upload-freshness checks', 'Reconciliation against CRM and finance'], process: ['Agree the lifecycle and revenue definitions', 'Map identifiers from first interaction to CRM', 'Implement webhook, API or upload connections', 'Validate freshness, matching and stage movement', 'Document ownership, failure handling and reporting'], faq: [{ question: 'Can you track qualified leads instead of only forms?', answer: 'Yes. We design the mapping from form or call through qualified lead, opportunity and won revenue where source data supports it.' }, { question: 'Do you replace the CRM?', answer: 'No. The CRM remains the system of record; Fixify connects its meaningful outcomes to measurement systems.' }], cta: 'Request a CRM-to-revenue measurement review', related: [{ label: 'GA4 Implementation', href: '/ga4-implementation/' }, { label: 'Measurement Strategy', href: '/measurement-strategy/' }, { label: 'BigQuery & BI', href: '/ga4-bigquery-bi/' }] },
  { slug: 'measurement-strategy', title: 'Define what should be measured before your team spends time implementing it.', eyebrow: 'Measure / strategy and tracking plans', seoTitle: 'Analytics Measurement Strategy and Tracking Plans | Fixify', description: 'Define KPIs, event taxonomies, ownership, governance and implementation priorities before building your analytics system.', primaryKeyword: 'analytics measurement strategy consultant', intro: 'A measurement strategy connects business questions, KPIs, event definitions, consent assumptions, ownership and acceptance criteria before implementation starts.', problem: 'Without a shared model, each platform becomes a new interpretation of the business and teams spend time implementing events that no decision actually needs.', deliverables: ['Business-question and KPI map', 'Measurement plan and event taxonomy', 'Parameter, property and metric dictionary', 'Data ownership and consent assumptions', 'QA acceptance criteria', 'Prioritized implementation roadmap and governance model'], process: ['Interview stakeholders and map decisions', 'Define the smallest useful measurement model', 'Document ownership, dependencies and assumptions', 'Prioritize implementation by business risk and value', 'Create the handover and change-management approach'], faq: [{ question: 'Is a measurement strategy only for large teams?', answer: 'No. A clear plan is often most valuable for small teams because it prevents wasted implementation and unclear ownership.' }, { question: 'Can this feed an existing GA4 or GTM project?', answer: 'Yes. The output is designed to guide an existing implementation as well as a new one.' }], cta: 'Book a measurement architecture workshop', related: [{ label: 'GA4 Implementation', href: '/ga4-implementation/' }, { label: 'Google Tag Manager', href: '/google-tag-manager/' }, { label: 'CRM & Offline Conversions', href: '/crm-offline-conversions/' }] },
  { slug: 'ga4-bigquery-bi', title: 'Join marketing, analytics, CRM and revenue data into reporting your teams can actually use.', eyebrow: 'Decide / BigQuery and BI', seoTitle: 'GA4 BigQuery, BI and Looker Studio Services | Fixify', description: 'Connect GA4, advertising, CRM and revenue data through BigQuery, data models and decision-ready Looker Studio reporting.', primaryKeyword: 'GA4 BigQuery and Looker Studio', intro: 'Dashboards become useful when definitions, sources, transformations and ownership are visible. Fixify connects GA4, advertising, CRM and revenue data into reporting with clear assumptions.', problem: 'Reporting often shows activity without explaining how the numbers relate to qualified leads, refunds, cancellations, revenue or operational records.', deliverables: ['BigQuery export and dataset architecture', 'Marketing data model and identity assumptions', 'Ad spend, GA4, CRM and revenue joins', 'Metric dictionary and attribution views', 'Executive, channel and diagnostic dashboards', 'Alerts, freshness checks and documentation'], process: ['Define decisions and the metrics needed to support them', 'Inventory sources and reconcile definitions', 'Build the model and reporting layer', 'Validate joins, freshness and edge cases', 'Handover ownership and change-management guidance'], faq: [{ question: 'Do you only build Looker Studio dashboards?', answer: 'No. We start with definitions and data relationships, then select the reporting layer that fits the team.' }, { question: 'Can you work with existing BigQuery models?', answer: 'Yes. We can review existing tables, document assumptions and focus the work on gaps that affect decisions.' }], cta: 'Review a reporting and data-modeling scope', related: [{ label: 'Measurement Strategy', href: '/measurement-strategy/' }, { label: 'CRM & Offline Conversions', href: '/crm-offline-conversions/' }, { label: 'Measurement QA', href: '/measurement-qa-monitoring/' }] },
  { slug: 'measurement-qa-monitoring', title: 'Catch tracking failures before they become reporting problems.', eyebrow: 'Govern / QA and monitoring', seoTitle: 'Analytics QA, Tracking Monitoring and Data Quality | Fixify', description: 'Catch broken tags, schema changes, consent failures, stale feeds and conversion discrepancies before they become reporting problems.', primaryKeyword: 'tracking QA and monitoring', intro: 'Good measurement is not a one-time release. Fixify creates practical checks for event schemas, consent states, browser/server behavior, feeds and conversion discrepancies.', problem: 'Tracking breaks after releases, ownership changes and platform updates when there is no repeatable QA or monitoring loop.', deliverables: ['Pre-launch QA checklist', 'Release regression and event-schema testing', 'Consent-state and browser/server checks', 'Feed freshness and conversion discrepancy rules', 'Incident severity and escalation model', 'Monthly health reporting and support options'], process: ['Identify critical events, sources and failure modes', 'Define automated or repeatable checks', 'Test current coverage and create a baseline', 'Set thresholds, ownership and escalation', 'Review results and improve the monitoring loop'], faq: [{ question: 'Can monitoring work without a large engineering team?', answer: 'Yes. We prioritize the smallest useful set of checks and document how a marketing or analytics owner can operate them.' }, { question: 'Do you monitor revenue directly?', answer: 'We can monitor the measurement signals and discrepancies your systems expose; finance remains the owner of financial truth.' }], cta: 'Ask about ongoing measurement QA', related: [{ label: 'GA4 Audit', href: '/ga4-audit/' }, { label: 'Google Tag Manager', href: '/google-tag-manager/' }, { label: 'Consent Mode & CMP', href: '/consent-mode-cmp/' }] },
]

